# Generic helper to decide removal based on year
import operator

def should_remove(release_year, threshold_year, mode):
    ops = {
        "before": operator.lt,
        "after": operator.gt,
        "in_or_before": operator.le,
        "in_or_after": operator.ge,
    }
    return ops[mode](release_year, threshold_year)

# Generic library removal loop
page_index = 0
while True:
    page = apis.spotify.show_song_library(access_token=access_token, page_index=page_index)
    if not page:
        break
    for item in page:
        song = apis.spotify.show_song(song_id=item.song_id)
        if should_remove(song.release_date.year, threshold_year, mode):
            apis.spotify.remove_song_from_library(access_token=access_token, song_id=song.song_id)
    page_index += 1
